class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        if m == 1 or n == 1:
            return 1
        if m < n:
            m, n = n, m

        res = j = 1
        for i in range(m, m + n - 1):
            res *= i
            res //= j
            j += 1

        return res

var uniquePaths = function(m, n) {
    if (m === 1 || n === 1) {
        return 1;
    }
    if (m < n) {
        [m, n] = [n, m];
    }

    let res = 1, j = 1;
    for (let i = m; i < m + n - 1; i++) {
        res *= i;
        res = Math.floor(res / j);
        j++;
    }

    return res;
};

